/* Local helper: generate src/builtin.inc, src/version.h, src/config_opts.inc
   for a manual (non-autotools) test build. Not part of the jq build. */
#include <stdio.h>

int main(void) {
  FILE *in = fopen("src/builtin.jq", "r");
  FILE *out = fopen("src/builtin.inc", "w");
  if (!in || !out) { perror("open"); return 1; }
  int c, bol = 1;
  while ((c = fgetc(in)) != EOF) {
    if (bol) { fputc('"', out); bol = 0; }
    if (c == '\n') { fputs("\\n\"\n", out); bol = 1; continue; }
    if (c == '"' || c == '\\') fputc('\\', out);
    fputc(c, out);
  }
  if (!bol) fputs("\\n\"\n", out);
  fclose(in);
  fclose(out);

  out = fopen("src/version.h", "w");
  fputs("#define JQ_VERSION \"1.7-test\"\n", out);
  fclose(out);
  out = fopen("src/config_opts.inc", "w");
  fputs("#define JQ_CONFIG \"(manual test build)\"\n", out);
  fclose(out);
  return 0;
}

